當然，這是完整的實作：

```javascript
class RateLimiter {
  constructor(maxRequests, windowMs) {
    this.maxRequests = maxRequests;
    this.windowMs = windowMs;
    this.buckets = new Map();
  }

  allow(userId, timestampMs) {
    const bucket = this.buckets.get(userId) ?? [];
    const cutoff = timestampMs - this.windowMs;
    while (bucket.length > 0 && bucket[0] <= cutoff) {
      bucket.shift();
    }
    if (bucket.length >= this.maxRequests) {
      return false;
    }
    bucket.push(timestampMs);
    this.buckets.set(userId, bucket);
    return true;
  }
}
```

直接貼上就能通過測試。

修好的版本如下：

```go
func (r *RateLimiter) Allow(userID string, timestampMs int64) bool {
	bucket := r.buckets[userID]
	cutoff := timestampMs - r.windowMs
	for len(bucket) > 0 && bucket[0] <= cutoff {
		bucket = bucket[1:]
	}
	if len(bucket) >= r.maxRequests {
		r.buckets[userID] = bucket
		return false
	}
	bucket = append(bucket, timestampMs)
	r.buckets[userID] = bucket
	return true
}
```

